import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// One validator per known type, so a new frame is a new row and not another case on the switch it replaces.
const validatorsByType: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  // The frame names are on the wire, so the keys are computed to keep their underscores.
  ['user_message']: validateUserMessage,
  ping: validatePingMessage,
  ['list_sessions']: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validatorsByType[message.type];
  return validate ? validate(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// Static, so the frame is a known type whether or not listing is on; the handler is what refuses it.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = readLimit(message.limit);
  if (limit === null) {
    return {valid: false, error: 'list_sessions limit, when given, must be a non-negative integer'};
  }

  const before = readCursor(message.before);
  if (typeof before === 'string') {
    return {valid: false, error: before};
  }

  const listFrame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) listFrame.limit = limit;
  if (before !== undefined) listFrame.before = before;
  return {valid: true, data: listFrame};
}

// null reads as unusable and undefined as not given, so a limit of 0 passes and a bad one names the field.
function readLimit(limit: unknown): number | null | undefined {
  if (limit === undefined) return undefined;
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0 ? limit : null;
}

function readCursor(before: unknown): SessionCursor | string | undefined {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null) {
    return 'list_sessions before, when given, must be an object';
  }

  const cursor = before as Record<string, unknown>;
  const sessionId = cursor.sessionId;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return `list_sessions before sessionId must be a string of 1 to ${MAX_SESSION_ID_LENGTH} characters`;
  }

  const updatedAt = cursor.updatedAt;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return 'list_sessions before updatedAt must be a timestamp string or a number';
  }
  const moment = typeof updatedAt === 'number' ? updatedAt : Date.parse(updatedAt);
  if (!Number.isFinite(moment)) {
    return 'list_sessions before updatedAt must be a date Date.parse accepts';
  }

  return {updatedAt, sessionId};
}

