  hal.wss.on('close', () => scratchLog('wssClose', {port}));
  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  client.on('error', error => scratchLog('clientError', {url, error: String(error)}));
  client.on('unexpected-response', (_req, res) =>
    scratchLog('clientUnexpectedResponse', {url, status: (res as {statusCode?: number}).statusCode})
  );
  scratchLog('clientOpen', {url});
  clients.push(client);
  return client;
};

