import {once} from 'node:events';
import type {IncomingMessage} from 'node:http';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './ws/subprotocol.js';
import type {WsAuthenticator} from '../types/auth.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {setLogger} from '../shared/logger.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';

// Real upgrades over a real socket: what the 101 carries is the contract, and no double can observe it.

const TOKEN = 'super-secret-token';

interface Handshake {
  answered: string | undefined;
  leakedHeaders: string[];
  socketProtocol: string;
  authorization: string | undefined;
}

const signal = () => {
  let release = (): void => undefined;
  const fired = new Promise<void>(resolve => {
    release = resolve;
  });
  return {fired, release: () => release()};
};

const admitEveryone: WsAuthenticator = async () => ({id: 'u1'});

const engine = async (wsAuth: WsAuthenticator = admitEveryone) => {
  // Read at connect: the close handler clears authHeaders, so a post-close read would see nothing.
  const bearers: Array<string | undefined> = [];
  const serverSockets: WebSocket[] = [];
  const disconnected = signal();
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth,
    sessionStore: new InMemorySessionStore(),
    orchestrator: {} as ChatOrchestrator,
    onConnect: session => void bearers.push(session.authHeaders?.authorization),
    onDisconnect: disconnected.release,
  });
  hal.wss.on('connection', socket => void serverSockets.push(socket));
  await hal.start(0);
  const {port} = hal.server.address() as AddressInfo;
  return {hal, bearers, serverSockets, disconnected, url: `ws://127.0.0.1:${port}/hal/ws/c1`};
};

// Connect, ping, close: the whole lifecycle a credential could be logged in.
const roundTrip = async (url: string, offer: string[], headers: Record<string, string>) => {
  const client = new WebSocket(url, offer, {headers});
  // Both listened for before either is awaited: the connected frame can land in the same tick as the 101.
  const upgraded = once(client, 'upgrade');
  const connected = once(client, 'message');
  const [response] = (await upgraded) as [IncomingMessage];
  await connected;
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await once(client, 'message');
  client.close();
  return response;
};

const handshake = async (offer: string[], headers: Record<string, string> = {}): Promise<Handshake> => {
  const {hal, bearers, serverSockets, disconnected, url} = await engine();
  const response = await roundTrip(url, offer, headers);
  await disconnected.fired;
  await hal.stop();

  const [bearer] = bearers;
  const [serverSocket] = serverSockets;
  const {rawHeaders} = response;
  return {
    answered: response.headers['sec-websocket-protocol'],
    leakedHeaders: rawHeaders.filter(value => value.includes(TOKEN)),
    socketProtocol: serverSocket.protocol,
    authorization: bearer,
  };
};

// Raced against open, so a server that still accepts an offer fails the test instead of hanging it.
const clientOutcome = (client: WebSocket): Promise<string> =>
  Promise.race([
    once(client, 'error').then(([error]) => (error as Error).message),
    once(client, 'open').then(() => 'opened'),
  ]);

// The authenticator the docs recommend: it reads the credential the way the engine does.
const readsSubprotocol: WsAuthenticator = async request =>
  credentialFromSubprotocol(request.headers['sec-websocket-protocol']) ? {id: 'u1'} : null;

// An offer without the marker is answered with no subprotocol, which the ws client fails after the 101.
const refusedHandshake = async (offer: string[]) => {
  const {hal, disconnected, url} = await engine();
  const client = new WebSocket(url, offer);
  const upgraded = once(client, 'upgrade');
  const outcome = clientOutcome(client);
  const [response] = (await upgraded) as [IncomingMessage];
  const clientError = await outcome;
  client.close();
  await disconnected.fired;
  await hal.stop();
  return {
    answered: response.headers['sec-websocket-protocol'],
    leakedHeaders: response.rawHeaders.filter(value => value.includes(TOKEN)),
    clientError,
  };
};

describe('the WebSocket handshake', () => {
  const lines: string[] = [];

  beforeEach(() => {
    lines.length = 0;
    const collect = (category: string, message: string, fields?: Record<string, unknown>) =>
      void lines.push(JSON.stringify({category, message, fields}));
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  it('answers a hal.v1 and token offer with hal.v1 alone, and forwards the token as a bearer', async () => {
    expect(await handshake([HAL_WS_SUBPROTOCOL, TOKEN])).toEqual({
      answered: HAL_WS_SUBPROTOCOL,
      leakedHeaders: [],
      socketProtocol: HAL_WS_SUBPROTOCOL,
      authorization: `Bearer ${TOKEN}`,
    });
  });

  it('connects a client offering only the marker, reading its credential from the Authorization header', async () => {
    expect(await handshake([HAL_WS_SUBPROTOCOL], {Authorization: 'Bearer from-header'})).toEqual({
      answered: HAL_WS_SUBPROTOCOL,
      leakedHeaders: [],
      socketProtocol: HAL_WS_SUBPROTOCOL,
      authorization: 'Bearer from-header',
    });
  });

  it('answers a bare-token offer with no subprotocol, so the client fails it and no response header holds the token', async () => {
    expect(await refusedHandshake([TOKEN])).toEqual({
      answered: undefined,
      leakedHeaders: [],
      clientError: 'Server sent no subprotocol',
    });
  });

  it('refuses a bare-token offer with 401 when the authenticator reads its credential with credentialFromSubprotocol', async () => {
    const {hal, url} = await engine(readsSubprotocol);
    const client = new WebSocket(url, [TOKEN]);

    const clientError = await clientOutcome(client);
    client.close();
    await hal.stop();

    expect(clientError).toBe('Unexpected server response: 401');
  });

  it('writes no offered value to any log line from connect to close, in either shape', async () => {
    await handshake([HAL_WS_SUBPROTOCOL, TOKEN]);
    await refusedHandshake([TOKEN]);

    expect(lines.filter(line => line.includes(TOKEN))).toEqual([]);
  });
});

import net from 'node:net';
import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {WsAuthenticator} from '../types/auth.js';
import {setLogger} from '../shared/logger.js';

// Raw requests over a real socket: a ws client always sends a Host and a valid target, so it cannot send these.

const admitEveryone: WsAuthenticator = async () => ({id: 'u1'});
const REPLY_WAIT_MS = 2_000;

type LoggedLine = {level: string; category: string; message: string; fields?: Record<string, unknown>};

const logged: LoggedLine[] = [];
const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
  void logged.push({level, category, message, fields});

const upgradeRequest = (target: string, hostLine: string): string =>
  `GET ${target} HTTP/1.1\r\n${hostLine}Connection: Upgrade\r\nUpgrade: websocket\r\n` +
  'Sec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n';

// The first status line the server writes back, or a marker when it writes nothing, so a regression fails, not hangs.
const statusLineFor = async (wsAuth: WsAuthenticator, request: string): Promise<string> => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth,
    sessionStore: new InMemorySessionStore(),
    orchestrator: {} as ChatOrchestrator,
  });
  // Only an upgraded request opens a connection; waiting on its close keeps its log line inside the test.
  const serverClosed = new Promise<void>(resolve => {
    hal.wss.once('connection', connection => connection.once('close', () => resolve()));
  });
  await hal.start(0);
  const {port} = hal.server.address() as AddressInfo;
  const reply = await new Promise<string>(resolve => {
    const socket = net.connect(port, '127.0.0.1', () => socket.write(request));
    const finish = (line: string): void => {
      clearTimeout(timer);
      socket.destroy();
      resolve(line);
    };
    const timer = setTimeout(() => finish('(no reply)'), REPLY_WAIT_MS);
    socket.once('data', chunk => finish(String(chunk).split('\r\n')[0]));
    socket.once('close', () => finish('(closed without a reply)'));
  });
  await Promise.race([serverClosed, new Promise(resolve => setTimeout(resolve, 50))]);
  await hal.stop();
  return reply;
};

describe('an upgrade request the server cannot read', () => {
  beforeAll(() => {
    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
  });

  beforeEach(() => {
    logged.length = 0;
  });

  afterAll(() => {
    setLogger();
  });

  it('answers an empty Host, a missing Host and a // target with 400 instead of throwing out of the upgrade listener', async () => {
    const replies = {
      emptyHost: await statusLineFor(admitEveryone, upgradeRequest('/hal/ws', 'Host:\r\n')),
      absentHost: await statusLineFor(admitEveryone, upgradeRequest('/hal/ws', '')),
      doubleSlash: await statusLineFor(admitEveryone, upgradeRequest('//', 'Host: example.com\r\n')),
    };

    expect(replies).toEqual({
      emptyHost: 'HTTP/1.1 400 Bad Request',
      absentHost: 'HTTP/1.1 400 Bad Request',
      doubleSlash: 'HTTP/1.1 400 Bad Request',
    });
  });

  it('answers 500 when the authenticator throws synchronously instead of rejecting', async () => {
    const throwsSynchronously: WsAuthenticator = () => {
      throw new Error('authenticator bug');
    };

    const reply = await statusLineFor(throwsSynchronously, upgradeRequest('/hal/ws', 'Host: example.com\r\n'));

    expect(reply).toBe('HTTP/1.1 500 Internal Server Error');
  });

  it('logs a throwing or rejecting authenticator by its error type alone, never its message', async () => {
    const request = upgradeRequest('/hal/ws', 'Host: example.com\r\n');
    const throwsSecret: WsAuthenticator = () => {
      throw new Error('bad token super-secret');
    };
    const rejectsSecret: WsAuthenticator = () => Promise.reject(new TypeError('bad token super-secret'));

    const replies = {
      throws: await statusLineFor(throwsSecret, request),
      rejects: await statusLineFor(rejectsSecret, request),
    };

    expect({
      replies,
      failures: logged.filter(line => line.message === 'authenticator failed'),
      leaked: JSON.stringify(logged).includes('super-secret'),
    }).toEqual({
      replies: {throws: 'HTTP/1.1 500 Internal Server Error', rejects: 'HTTP/1.1 500 Internal Server Error'},
      failures: [
        {level: 'error', category: 'ws', message: 'authenticator failed', fields: {errorType: 'Error'}},
        {level: 'error', category: 'ws', message: 'authenticator failed', fields: {errorType: 'TypeError'}},
      ],
      leaked: false,
    });
  });

  it('upgrades a request whose authenticator returns a user without a promise', async () => {
    const returnsPlainUser = (() => ({id: 'u1'})) as unknown as WsAuthenticator;

    const reply = await statusLineFor(returnsPlainUser, upgradeRequest('/hal/ws', 'Host: example.com\r\n'));

    expect(reply).toBe('HTTP/1.1 101 Switching Protocols');
  });

  it('still upgrades a well-formed request', async () => {
    const reply = await statusLineFor(admitEveryone, upgradeRequest('/hal/ws', 'Host: example.com\r\n'));

    expect(reply).toBe('HTTP/1.1 101 Switching Protocols');
  });
});

import net from 'node:net';
import request from 'supertest';
import type {Request, Response} from 'express';
import {createHalEngine} from './config.js';
import {log, setLogger} from './shared/logger.js';
import type {Logger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {HttpAuthMiddleware, WsAuthenticator} from './types/auth.js';
import {recordingSessionStore} from './infrastructure/writeSignalTestSupport.js';

// Both options below are declared on HalEngineConfig and were dropped at the forwarding site.

const base = {
  provider: {type: 'mock' as const},
  prompt: {identity: 'test'},
  auth: {ws: (async () => null) as unknown as WsAuthenticator},
};

describe('createHalEngine forwarding', () => {
  it('forwards an orchestrator hook, so one passed through the config actually fires', async () => {
    const seen: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {hooks: {beforeSession: async () => void seen.push('beforeSession')}},
    });
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(seen).toEqual(['beforeSession']);
  });

  it('forwards transport.port, so the server listens where the config said', async () => {
    const engine = createHalEngine({...base, transport: {port: 0}});

    await engine.start();
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheConfig: port !== 8086, real: port > 0}).toEqual({usedTheConfig: true, real: true});
  });

  it('lets an explicit start(port) win over the configured one', async () => {
    const engine = createHalEngine({...base, transport: {port: 8099}});

    await engine.start(0);
    const address = engine.server.address();
    const port = typeof address === 'object' && address !== null ? address.port : -1;
    await engine.stop();

    expect({usedTheArgument: port !== 8099, real: port > 0}).toEqual({usedTheArgument: true, real: true});
  });
});

// The option was declared on HalEngineConfig and read by nothing, so a supplied logger received no lines.
describe('createHalEngine logger forwarding', () => {
  afterEach(() => {
    setLogger();
  });

  it("delivers the package's own log lines to a supplied logger", async () => {
    const lines: {category: string; message: string}[] = [];
    const collect = (category: string, message: string) => void lines.push({category, message});
    const logger: Logger = {debug: collect, info: collect, warn: collect, error: collect};

    const engine = createHalEngine({...base, logger, transport: {port: 0}});
    await engine.start();
    await engine.stop();

    expect(lines).toContainEqual({category: 'server', message: 'HAL Engine started'});
  });

  // Asserts on a line logged AFTER construction: nothing logs during it, so an emptiness check cannot fail.
  it('leaves an already-supplied logger in place when the config names none', async () => {
    const lines: string[] = [];
    setLogger({
      debug: (_c: string, m: string) => void lines.push(m),
      info: (_c: string, m: string) => void lines.push(m),
      warn: (_c: string, m: string) => void lines.push(m),
      error: (_c: string, m: string) => void lines.push(m),
    });

    createHalEngine({...base});
    log.info('test', 'after construction');

    expect(lines).toEqual(['after construction']);
  });
});

describe('createHalEngine orchestrator hooks reach the orchestrator', () => {
  it('processes a message when the config declares no orchestrator key at all', async () => {
    const engine = createHalEngine({...base});
    const session: ChatSession = {
      sessionId: 's-noorch',
      userId: 'u1',
      entries: [{role: 'user', content: 'ping', timestamp: ''}],
    };

    const reply = await engine.orchestrator.processMessage(session);

    expect(reply).toContain('ping');
  });

  const replyThrough = async (engine: ReturnType<typeof createHalEngine>, sessionId: string): Promise<string> =>
    engine.orchestrator.processMessage({
      sessionId,
      userId: 'u1',
      entries: [{role: 'user', content: 'unwrapped', timestamp: ''}],
    });

  it('processes a message unchanged when the config declares no resilience block', async () => {
    const reply = await replyThrough(createHalEngine({...base}), 's-no-resilience');

    expect(reply).toEqual('Mock response to: "unwrapped" ');
  });

  it('processes a message to the same reply when the config declares a resilience block', async () => {
    const engine = createHalEngine({...base, resilience: {maxAttempts: 3, baseDelayMs: 0}});

    const reply = await replyThrough(engine, 's-resilience');

    expect(reply).toEqual('Mock response to: "unwrapped" ');
  });

  it('hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it', async () => {
    let received = 'never called';
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeModelResponse: async (_session, systemPrompt) => {
            received = systemPrompt;
            return systemPrompt;
          },
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-prompt',
      userId: 'u1',
      entries: [{role: 'user', content: 'hi', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(received).toBe('test');
  });

  it('fires the lifecycle hooks in documented order for a session that completes without error', async () => {
    const order: string[] = [];
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeSession: async () => void order.push('beforeSession'),
          beforeUserInput: async (_session, message) => {
            order.push('beforeUserInput');
            return message;
          },
          afterUserInput: async () => void order.push('afterUserInput'),
          beforeModelResponse: async (_session, systemPrompt) => {
            order.push('beforeModelResponse');
            return systemPrompt;
          },
          afterModelResponse: async () => void order.push('afterModelResponse'),
          afterSession: async () => void order.push('afterSession'),
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-order',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: ''}],
    };

    await engine.orchestrator.processMessage(session);

    expect(order).toEqual([
      'beforeSession',
      'beforeUserInput',
      'afterUserInput',
      'beforeModelResponse',
      'afterModelResponse',
      'afterSession',
    ]);
  });
});

// An unavailable port is a condition a consumer can handle, but only if start() lets them see it.
describe('createHalEngine on a port it cannot bind', () => {
  it('rejects instead of taking the process down with an unhandled error event', async () => {
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const engine = createHalEngine({...base, transport: {port: taken}});

    await expect(engine.start()).rejects.toMatchObject({code: 'EADDRINUSE'});

    await new Promise<void>(resolve => blocker.close(() => resolve()));
  });
});

// transport.additionalRoutes and transport.rootRoutes were declared but never forwarded to createApp.
describe('createHalEngine transport extension forwarding', () => {
  it('forwards transport.additionalRoutes to createApp so the route mounts under basePath', async () => {
    const engine = createHalEngine({
      ...base,
      transport: {
        additionalRoutes: (r: import('express').Router) => r.get('/ping', (_req, res) => res.json({ok: true})),
      },
    });

    const response = await request(engine.app).get('/hal/ping');
    const atRoot = await request(engine.app).get('/ping');

    expect({status: response.status, body: response.body, rootStatus: atRoot.status, rootBody: atRoot.body}).toEqual({
      status: 200,
      body: {ok: true},
      rootStatus: 404,
      rootBody: {error: 'Not Found'},
    });
  });

  it('leaves additionalRoutes and rootRoutes open while auth.http still guards the chat routes', async () => {
    const guarded: string[] = [];
    const refuse: HttpAuthMiddleware = (req, res) => {
      guarded.push(`${req.method} ${req.originalUrl}`);
      res.status(401).json({error: 'refused'});
    };
    const ok = (_req: Request, res: Response) => res.json({ok: true});
    const engine = createHalEngine({
      ...base,
      auth: {...base.auth, http: refuse},
      transport: {additionalRoutes: router => router.get('/ping', ok), rootRoutes: router => router.get('/status', ok)},
    });

    const statuses = await Promise.all(
      ['/hal/ping', '/status'].map(async path => (await request(engine.app).get(path)).status)
    );
    const chat = await request(engine.app).post('/hal/chats');

    expect({statuses, chat: chat.status, guarded}).toEqual({
      statuses: [200, 200],
      chat: 401,
      guarded: ['POST /hal/chats'],
    });
  });

  it('gives additionalRoutes and rootRoutes the parsed JSON body, the cookies and the CORS headers', async () => {
    const echo = (req: Request, res: Response) =>
      res.json({body: req.body as unknown, cookies: req.cookies as unknown});
    const engine = createHalEngine({
      ...base,
      transport: {
        corsOrigin: 'https://shop.example',
        additionalRoutes: router => router.post('/echo', echo),
        rootRoutes: router => router.post('/echo', echo),
      },
    });
    const call = async (path: string) => {
      const pending = request(engine.app).post(path);
      const response = await pending.set({Origin: 'https://shop.example', Cookie: 'theme=dark'}).send({city: 'Berlin'});
      return {body: response.body as unknown, origin: response.headers['access-control-allow-origin']};
    };

    const answered = await Promise.all([call('/hal/echo'), call('/echo')]);

    const expected = {body: {body: {city: 'Berlin'}, cookies: {theme: 'dark'}}, origin: 'https://shop.example'};
    expect(answered).toEqual([expected, expected]);
  });

  it("hands transport.errorHandler a route's synchronous throw and its rejected promise, and answers with its response", async () => {
    const engine = createHalEngine({
      ...base,
      transport: {
        rootRoutes: router => {
          router.get('/thrown', () => {
            throw new Error('thrown');
          });
          router.get('/rejected', () => Promise.reject(new Error('rejected')));
        },
        errorHandler: (error: unknown, _req, res, _next) =>
          void res.status(500).json({handled: error instanceof Error ? error.message : String(error)}),
      },
    });

    const thrown = await request(engine.app).get('/thrown');
    const rejected = await request(engine.app).get('/rejected');

    expect([thrown.body, rejected.body]).toEqual([{handled: 'thrown'}, {handled: 'rejected'}]);
  });

  it('answers 404 for a route added to engine.app after createHalEngine returns', async () => {
    const engine = createHalEngine({...base});
    engine.app.get('/late', (_req, res) => res.json({late: true}));

    const response = await request(engine.app).get('/late');

    expect({status: response.status, body: response.body}).toEqual({status: 404, body: {error: 'Not Found'}});
  });
});

